DECLARE num INT DEFAULT 0;
sumNumbers: LOOP
SET num = num + 1;
IF num > 10 THEN
LEAVE sumNumbers;
END IF;
IF num % 2 = 0 THEN
ITERATE sumNumbers;
END IF;
SET sum = sum + num;
